#!/usr/bin/env node
/**
 * Extract all unique enum values from shows.json to build mapping tables.
 * This helps us understand the cardinality of each field before minification.
 */

const fs = require('fs');
const path = require('path');

const showsFile = path.join(__dirname, '../../..', 'data/normalized/shows.json');

const data = JSON.parse(fs.readFileSync(showsFile, 'utf8'));

const enums = {
  status: new Set(),
  genre: new Set(),
  subgenres: new Set(),
  ageRestriction: new Set(),
  venues: new Map(), // venue -> venueName
  rooms: new Set(),
  companies: new Set(),
};

// Scan all shows
data.forEach(show => {
  enums.genre.add(show.genre);
  (show.subgenres || []).forEach(sg => enums.subgenres.add(sg));
  enums.ageRestriction.add(show.ageRestriction);
  enums.venues.set(show.venue, show.venueName);
  enums.rooms.add(show.room);
  enums.companies.add(show.company);

  (show.performances || []).forEach(perf => {
    enums.status.add(perf.status);
  });
});

// Convert to arrays and sort for consistent ordering
const result = {
  status: Array.from(enums.status).sort(),
  genre: Array.from(enums.genre).sort(),
  subgenres: Array.from(enums.subgenres).sort(),
  ageRestriction: Array.from(enums.ageRestriction).sort(),
  venues: Array.from(enums.venues.entries()).sort((a, b) => a[0].localeCompare(b[0])),
  rooms: Array.from(enums.rooms).sort(),
  companies: Array.from(enums.companies).sort(),
  stats: {
    totalShows: data.length,
    totalPerformances: data.reduce((sum, s) => sum + (s.performances?.length || 0), 0),
  }
};

console.log(JSON.stringify(result, null, 2));

