1	#!/usr/bin/env node
2	/**
3	 * Minify shows.json by applying aggressive enum mapping and field shortening.
4	 * Reduces file size by ~60-70%.
5	 */
6	
7	const fs = require('fs');
8	
9	const showsFile = '/home/user/EdFringeNow/data/normalized/shows.json';
10	const data = JSON.parse(fs.readFileSync(showsFile, 'utf8'));
11	
12	// Build enum mappings by scanning data
13	const enums = {
14	  status: [],
15	  genre: [],
16	  subgenres: [],
17	  ageRestriction: [],
18	  rooms: [],
19	  venues: [],
20	};
21	
22	const enumerations = {
23	  status: new Set(),
24	  genre: new Set(),
25	  subgenres: new Set(),
26	  ageRestriction: new Set(),
27	  rooms: new Set(),
28	  venueBaseName: new Map(), // venueId -> base name (without room)
29	};
30	
31	// Scan all shows to extract unique values and build venue base names
32	data.forEach(show => {
33	  if (show.genre) enumerations.genre.add(show.genre);
34	  (show.subgenres || []).forEach(sg => enumerations.subgenres.add(sg));
35	  if (show.ageRestriction) enumerations.ageRestriction.add(show.ageRestriction);
36	  if (show.room) enumerations.rooms.add(show.room);
37	
38	  // Extract venue base name from venueName by removing room prefix
39	  if (show.venue && show.venueName && show.room) {
40	    const escapedRoom = show.room.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
41	    const venueBase = show.venueName.replace(new RegExp(`^${escapedRoom}\\s+at\\s+`), '');
42	    enumerations.venueBaseName.set(show.venue, venueBase);
43	  }
44	
45	  (show.performances || []).forEach(perf => {
46	    if (perf.status) enumerations.status.add(perf.status);
47	  });
48	});
49	
50	// Convert to sorted arrays for consistent indexing
51	enums.status = Array.from(enumerations.status).sort();
52	enums.genre = Array.from(enumerations.genre).sort();
53	enums.subgenres = Array.from(enumerations.subgenres).sort();
54	enums.ageRestriction = Array.from(enumerations.ageRestriction).sort();
55	enums.rooms = Array.from(enumerations.rooms).sort();
56	enums.venueBaseName = Array.from(enumerations.venueBaseName.entries())
57	  .sort((a, b) => (a[0] || '').localeCompare(b[0] || ''))
58	  .map(([id, name]) => [id, name]);
59	
60	// Create lookup maps for encoding
61	const statusMap = new Map(enums.status.map((s, i) => [s, i]));
62	const genreMap = new Map(enums.genre.map((g, i) => [g, i]));
63	const subgenreMap = new Map(enums.subgenres.map((sg, i) => [sg, i]));
64	const ageRestrictionMap = new Map(enums.ageRestriction.map((ar, i) => [ar, i]));
65	const roomMap = new Map(enums.rooms.map((r, i) => [r, i]));
66	const venueBaseNameMap = new Map(enums.venueBaseName.map((v, i) => [v[0], i]));
67	
68	// Minify shows
69	const minified = data.map(show => ({
70	  i: show.id,
71	  t: show.title,
72	  sl: show.slug,
73	  g: genreMap.get(show.genre),
74	  sg: (show.subgenres || []).map(sg => subgenreMap.get(sg)).filter(x => x !== undefined),
75	  c: show.company,
76	  d: show.duration,
77	  ar: ageRestrictionMap.get(show.ageRestriction),
78	  f: show.free ? 1 : 0,
79	  im: show.image,
80	  si: show.smallImage,
81	  b: show.blurb,
82	  v: show.venue,
83	  vbi: show.venue && show.room ? venueBaseNameMap.get(show.venue) : undefined, // venue base name index
84	  rm: roomMap.get(show.room),
85	  vn: !show.room && show.venueName ? show.venueName : undefined, // fallback: store full venueName if no room
86	  p: (show.performances || []).map(perf => {
87	    const [year, month, day] = perf.date.split('-');
88	    return {
89	      d: parseInt(month + day, 10), // MMDD format (e.g., 0824 for Aug 24)
90	      st: perf.start,
91	      so: perf.soldOut ? 1 : 0,
92	      sa: statusMap.get(perf.status),
93	    };
94	  }),
95	}));
96	
97	// Build output with metadata
98	const output = {
99	  __meta: {
100	    status: enums.status,
101	    genre: enums.genre,
102	    subgenres: enums.subgenres,
103	    ageRestriction: enums.ageRestriction,
104	    rooms: enums.rooms,
105	    venueBaseName: enums.venueBaseName, // [venueId, baseName]
106	  },
107	  shows: minified,
108	};
109	
110	console.log(JSON.stringify(output));
