2	/**
3	 * Restore minified shows data back to full format (inverse of dehydrate).
4	 */
5	
6	const fs = require('fs');
7	
8	const minifiedFile = process.argv[2] || '/tmp/minified-shows.json';
9	
10	const minified = JSON.parse(fs.readFileSync(minifiedFile, 'utf8'));
11	const meta = minified.__meta;
12	
13	// Create reverse lookup maps
14	const statusMap = meta.status.map((s, i) => [i, s]).reduce((acc, [i, s]) => {
15	  acc[i] = s;
16	  return acc;
17	}, {});
18	
19	const genreMap = meta.genre.map((g, i) => [i, g]).reduce((acc, [i, g]) => {
20	  acc[i] = g;
21	  return acc;
22	}, {});
23	
24	const subgenreMap = meta.subgenres.map((sg, i) => [i, sg]).reduce((acc, [i, sg]) => {
25	  acc[i] = sg;
26	  return acc;
27	}, {});
28	
29	const ageRestrictionMap = meta.ageRestriction.map((ar, i) => [i, ar]).reduce((acc, [i, ar]) => {
30	  acc[i] = ar;
31	  return acc;
32	}, {});
33	
34	const roomMap = meta.rooms.map((r, i) => [i, r]).reduce((acc, [i, r]) => {
35	  acc[i] = r;
36	  return acc;
37	}, {});
38	
39	// Venue base names is an array of [venueId, baseName]
40	const venueBaseNameMap = meta.venueBaseName.map((v, i) => [i, v]).reduce((acc, [i, [venueId, baseName]]) => {
41	  acc[i] = [venueId, baseName];
42	  return acc;
43	}, {});
44	
45	// Rehydrate shows - reconstruct venueName from room and venue base name
46	const restored = minified.shows.map(show => {
47	  const room = show.rm !== undefined ? roomMap[show.rm] : null;
48	  let venueName = show.vn || null; // use stored venueName if available (fallback case)
49	
50	  if (show.vbi !== undefined && room) {
51	    const [venueId, baseName] = venueBaseNameMap[show.vbi];
52	    venueName = `${room} at ${baseName}`;
53	  }
54	
55	  return {
56	    id: show.i,
57	    title: show.t,
58	    slug: show.sl,
59	    genre: show.g !== undefined ? genreMap[show.g] : null,
60	    subgenres: (show.sg || []).map(i => subgenreMap[i]).filter(Boolean),
61	    company: show.c,
62	    duration: show.d,
63	    ageRestriction: show.ar !== undefined ? ageRestrictionMap[show.ar] : null,
64	    free: show.f === 1,
65	    image: show.im,
66	    smallImage: show.si,
67	    blurb: show.b,
68	    venue: show.v,
69	    venueName: venueName,
70	    room: room,
71	    performances: (show.p || []).map(perf => {
72	      const mmdd = String(perf.d).padStart(4, '0');
73	      const month = mmdd.substring(0, 2);
74	      const day = mmdd.substring(2, 4);
75	      return {
76	        date: `2026-${month}-${day}`,
77	        start: perf.st,
78	        soldOut: perf.so === 1,
79	        status: statusMap[perf.sa],
80	      };
81	    }),
82	  };
83	});
84	
85	console.log(JSON.stringify(restored));
