import { chromium } from '/usr/lib/node_modules/playwright/index.mjs';
import { spawn } from 'node:child_process';

const PORT = 8137;
const server = spawn('python3', ['-m', 'http.server', String(PORT)], {
  cwd: '/home/user/EdFringeNow', stdio: 'ignore',
});
await new Promise((r) => setTimeout(r, 800));

const errors = [];
let browser;
try {
  browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
  const page = await browser.newPage();
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

  await page.goto(`http://localhost:${PORT}/plan/index.html`, { waitUntil: 'networkidle' });

  // Open the debug menu (pill) then click "Add 10 random shows" — this awaits
  // ensureData(), which fetches shows.min.json + venues.json and rehydrates.
  await page.click('#debugRandomBtn', { force: true });

  // Lanes are built from the rehydrated catalogue; wait for them to appear.
  await page.waitForSelector('#lanes .lane, .lane-label', { timeout: 8000 });

  const laneCount = await page.$$eval('#lanes > *', (els) => els.length);
  const firstTitle = await page.$eval('.lane-label', (el) => el.textContent.trim()).catch(() => '');
  const errShown = await page.$eval('#errorState', (el) => !el.hidden).catch(() => false);

  console.log('lanes rendered:', laneCount);
  console.log('first lane label:', JSON.stringify(firstTitle));
  console.log('errorState visible:', errShown);
  console.log('console/page errors:', errors.length ? errors : 'none');

  const ok = laneCount > 0 && !errShown && errors.length === 0;
  console.log(ok ? '✅ SMOKE PASS — planner loaded & rehydrated the catalogue' : '❌ SMOKE FAIL');
  process.exitCode = ok ? 0 : 1;
} catch (e) {
  console.log('❌ SMOKE ERROR:', e.message);
  console.log('errors seen:', errors);
  process.exitCode = 1;
} finally {
  if (browser) await browser.close();
  server.kill();
}

