const PORT = 8139;
const server = spawn('python3', ['-m', 'http.server', String(PORT)], {
  cwd: '/home/user/EdFringeNow', stdio: 'ignore',
});
await new Promise((r) => setTimeout(r, 1000));

const errors = [];
const responses = {};
let browser;
try {
  browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
  const page = await browser.newPage();
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('response', (r) => {
    const u = r.url();
    if (u.includes('shows.min.json')) responses.min = r.status();
    if (u.endsWith('venues.json')) responses.venues = r.status();
    if (u.includes('shows.json') && !u.includes('.min.')) responses.fullMaster = r.status();
  });

  await page.goto(`http://localhost:${PORT}/plan/index.html`, { waitUntil: 'networkidle' });

  // "Try the sample favourites" — runs ensureData() (fetch + rehydrate the
