  console.log('lanes rendered:', laneLabels.length, '→', JSON.stringify(laneLabels));
  console.log('errorState visible:', errShown);
  console.log('errors:', errors.length ? errors : 'none');

  const ok = responses.min === 200 && responses.venues === 200 &&
             responses.fullMaster === undefined &&
             laneLabels.length > 0 && !errShown && errors.length === 0;
  console.log(ok ? '✅ SMOKE PASS — planner fetched shows.min.json + venues.json and rehydrated the catalogue'
                 : '❌ SMOKE FAIL');
  process.exitCode = ok ? 0 : 1;
} catch (e) {
  console.log('❌ SMOKE ERROR:', e.message);
  console.log('errors seen:', errors);
  process.exitCode = 1;
} finally {
  if (browser) await browser.close();
  server.kill();
}

